        editor.move_right();
        assert_eq!(editor.caret, 3, "one three-byte character");
        editor.insert("x");
        assert_eq!(editor.text, "构x建");
        editor.backspace();
        assert_eq!(editor.text, "构建");
        assert_eq!(editor.caret, 3);
