    #[test]
    fn wheel_accumulator_preserves_fractional_residue_across_events() {
        // Eight trackpad ticks of 0.375 units (binary-exact) must add up to exactly 3 whole
        // units drained, never 0 (per-event truncation) and never 4 (double counting).
        let mut remainder = 0.0;
        let mut drained = 0;
        for _ in 0..8 {
            remainder += 0.375;
            drained += drain_whole_units(&mut remainder, 1.0);
        }
        assert_eq!(drained, 3);
        assert_eq!(remainder, 0.0);

        // Whole-line wheel notches with a 17px cell drain exactly one line per 17px, residue 8.
        let mut pixels = 25.0;
        assert_eq!(drain_whole_units(&mut pixels, 17.0), 1);
        assert!((pixels - 8.0).abs() < 1e-9);
    }

    /// PIN — a run of notches inside one turn of the loop is **one** notch, and
    /// it is the same notch arithmetically.
    ///
    /// The coalescing this pins is worth having only if it changes nothing but
    /// the count: a burst that scrolled a different distance from the notches
    /// that made it would be a wheel that behaves differently on a busy machine,
    /// which is the opposite of the point. So the two halves are asserted
    /// together — the burst is one delta, and that delta is the sum.
    #[test]
    fn wheel_burst_collapses_a_run_of_notches_without_changing_the_distance() {
        let mut burst = WheelBurst::of(MouseScrollDelta::LineDelta(0.0, -1.0));
        for _ in 0..4 {
            burst = burst
                .plus(MouseScrollDelta::LineDelta(0.0, -1.0))
                .expect("a line delta merges into a line burst");
        }
        assert_eq!(
            burst.delta(),
            MouseScrollDelta::LineDelta(0.0, -5.0),
            "five detents in one turn are five lines, spent once"
        );

        // The same for the currency a trackpad speaks, on both axes: a tilt
        // wheel's horizontal travel is summed beside the vertical, not dropped.
        let mut pixels = WheelBurst::of(MouseScrollDelta::PixelDelta(PhysicalPosition::new(
            3.0, -12.5,
        )));
        pixels = pixels
            .plus(MouseScrollDelta::PixelDelta(PhysicalPosition::new(
                -1.0, -7.5,
            )))
            .expect("a pixel delta merges into a pixel burst");
        assert_eq!(
            pixels.delta(),
            MouseScrollDelta::PixelDelta(PhysicalPosition::new(2.0, -20.0))
        );

        // **The two currencies do not add.** A device that changes its mind
        // mid-burst is told to spend what is held first, rather than have its
        // lines quietly reinterpreted as pixels.
        assert_eq!(
            WheelBurst::of(MouseScrollDelta::LineDelta(0.0, -1.0)).plus(
                MouseScrollDelta::PixelDelta(PhysicalPosition::new(0.0, -1.0))
            ),
            None
        );
        assert_eq!(
            WheelBurst::of(MouseScrollDelta::PixelDelta(PhysicalPosition::new(
                0.0, -1.0
            )))
            .plus(MouseScrollDelta::LineDelta(0.0, -1.0)),
            None
        );
    }

    #[test]
    fn wheel_accumulator_truncates_symmetrically_and_never_flips_sign_on_reversal() {
        // +0.6 then -0.7: neither direction has accrued a whole unit, so nothing drains and the
        // residue nets out — reversal must not manufacture a step from opposite-sign residue.
        let mut remainder = 0.0;
        remainder += 0.6;
        assert_eq!(drain_whole_units(&mut remainder, 1.0), 0);
        remainder += -0.7;
        assert_eq!(drain_whole_units(&mut remainder, 1.0), 0);
        assert!((remainder + 0.1).abs() < 1e-9);

        // A full downward unit drains as -1 with the same magnitude rules as upward.
        let mut down = -1.4;
        assert_eq!(drain_whole_units(&mut down, 1.0), -1);
        assert!((down + 0.4).abs() < 1e-9);
    }

    #[test]
    fn disconnected_math_dispatch_downgrades_once_and_leaves_the_real_session_usable() {
        let start = Instant::now();
        let mut session =
            DualPlaneSession::new(NonZeroU32::new(40).unwrap(), NonZeroU32::new(2).unwrap());
        session.feed_at(b"$$x$$\x1b[?25l", start).unwrap();
        assert_eq!(
            session.advance_live_stability(start + bt_term::LIVE_MATH_STABLE_INTERVAL),
            1
        );
        let (tasks, receiver) = mpsc::channel();
        drop(receiver);
        let (scale_tasks, _scale_receiver) = mpsc::channel();
        let mut running = true;
        let mut notice_pending = false;

        assert!(dispatch_pending_math_tasks(
            probe_leaf(),
            &mut session,
            &tasks,
            &scale_tasks,
            &mut running,
            &mut notice_pending,
        ));
        assert!(!running);
        assert!(notice_pending);
        session.feed(b"\r\nterminal-still-running").unwrap();
        assert!(
            session
                .terminal()
                .visible_text()
                .iter()
                .any(|row| row.contains("terminal-still-running"))
        );

        assert_eq!(
            take_math_worker_notice(&mut notice_pending),
            Some(math_worker_stopped_notice())
        );
        assert!(!notice_pending);
        assert_eq!(take_math_worker_notice(&mut notice_pending), None);
        assert!(!dispatch_pending_math_tasks(
            probe_leaf(),
            &mut session,
            &tasks,
            &scale_tasks,
            &mut running,
            &mut notice_pending,
        ));
        assert!(
            !notice_pending,
            "the user-visible downgrade notice is one-shot"
        );
    }

    fn scale_task(content_key: &str, width: u32) -> bt_term::InlineImageScaleTask {
        bt_term::InlineImageScaleTask {
            occurrence_id: 0,
            content_key: content_key.to_owned(),
            rgba: Arc::from([0_u8, 0, 0, 255]),
            width_px: 1,
            height_px: 1,
            display_width_px: width,
            display_height_px: width,
        }
    }

    /// RED: a divider storm used to put every intermediate Lanczos3 request on the one FIFO.
    /// The worker must execute only the newest size for one content/purpose, while preserving a
    /// different purpose as an independent question.
    #[test]
    fn scale_worker_drag_storm_discards_superseded_work_and_completes_the_latest() {
        let (sender, receiver) = mpsc::channel();
        for width in 1..=128 {
            sender
                .send(ScaleWorkerRequest::Preview {
                    leaf: probe_leaf(),
                    task: scale_task("same-path", width),
                })
                .unwrap();
        }
        sender
            .send(ScaleWorkerRequest::Peek {
                leaf: probe_leaf(),
                task: scale_task("same-path", 17),
            })
            .unwrap();
        drop(sender);

        let mut executed = Vec::new();
        run_scale_worker(receiver, |request| {
            executed.push((request.purpose(), request.task().display_width_px));
        });

        assert_eq!(
            executed,
            vec![(ScalePurpose::Preview, 128), (ScalePurpose::Peek, 17)]
        );
    }

    /// RED: an obsolete completion must not clear the newest pending target, and the newest
    /// completion must retire "Loading image..." instead of leaving the preview stuck forever.
    #[test]
    fn preview_loading_survives_a_stale_scale_answer_then_clears_on_the_latest() {
        let mut preview = PreviewImageState::new(PathBuf::from("storm.png"));
        preview.pending = Some(("same-path".to_owned(), 320, 180));

        assert!(
            !preview.accept_scaled(bt_term::scale_inline_image(&scale_task("same-path", 160,)))
        );
        assert_eq!(preview.message(), Some("Loading storm.png…".to_owned()));

        assert!(preview.accept_scaled(bt_term::scale_inline_image(
            &bt_term::InlineImageScaleTask {
                display_width_px: 320,
                display_height_px: 180,
                ..scale_task("same-path", 320)
            },
        )));
        assert_eq!(preview.message(), None);
    }

    // ── the picture keeps its identity across a change of host ─────────────
    //
    // User report, 2026-08-17: "undock an image preview into a float and the
    // picture disappears; dock it back and it still never loads". Three pins,
    // one per link of the chain that broke.

    fn pending_picture(path: &str, target: PeekThumbnailTarget) -> PreviewImageState {
        let mut picture = PreviewImageState::new(PathBuf::from(path));
        picture.pending = Some(target);
        picture
    }

    /// RED before the fix: the resample was delivered to whoever held the
    /// texture lane *when it landed*, and `pop_out_preview` hands the lane back
    /// on the way out — so a question asked by a docked pane and answered while
    /// it was a window went to nobody, and the ledger entry it should have
    /// retired stayed set for good ("already asked" for every later refit).
    ///
    /// The move here is exactly `pop_out_preview`'s: the pane is taken out of the
    /// plane whole and put back under a float's address.
    #[test]
    fn a_picture_torn_off_into_a_window_still_takes_delivery_of_its_resample() {
        let seat = SeatId(7);
        let float = 3_u64;
        let target: PeekThumbnailTarget = ("push-pin".to_owned(), 320, 180);
        let mut panes = PreviewPanes::default();
        panes.entry(PreviewSurface::Seat(seat)).image =
            Some(pending_picture("push-pin.png", target.clone()));

        assert_eq!(
            panes.awaiting_scale(&target),
            Some(PreviewSurface::Seat(seat)),
            "the docked pane is the one that asked"
        );

        // `pop_out_preview`: the view travels whole, under a new address.
        let pane = panes.remove(PreviewSurface::Seat(seat)).expect("the pane");
        *panes.entry(PreviewSurface::Float(float)) = pane;

        assert_eq!(
            panes.awaiting_scale(&target),
            Some(PreviewSurface::Float(float)),
            "and the window it became is still the one that asked"
        );
        // The texture lane, meanwhile, is nobody's — `pop_out_preview` hands it
        // back on the way out, because a window paints its own picture. That is
        // exactly why the answer must not be routed through it: at this instant
        // there is no lane holder to hand it to, and the question above would
        // then stay outstanding for good.
        let lane: Option<PreviewSurface> = None;
        assert_ne!(
            lane,
            panes.awaiting_scale(&target),
            "the picture that asked is not the pane that happens to hold the lane"
        );

        let surface = panes.awaiting_scale(&target).expect("an asker");
        let picture = panes
            .entry(surface)
            .image
            .as_mut()
            .expect("the picture that asked");
        assert!(
            picture.accept_scaled(bt_term::scale_inline_image(
                &bt_term::InlineImageScaleTask {
                    display_width_px: 320,
                    display_height_px: 180,
                    ..scale_task("push-pin", 320)
                },
            )),
            "the answer lands on the picture that asked for it"
        );
        assert_eq!(picture.pending, None, "and retires the question with it");
        assert!(picture.raster.is_some(), "leaving the pixels behind");
        assert_eq!(
            panes.awaiting_scale(&target),
            None,
            "nothing is left waiting on an answer that has arrived"
        );
    }

    /// RED before the fix: `dock_preview_float` moved the view back onto a pane
    /// and never asked for the texture lane again, so the re-docked picture was
    /// never rasterised — head, foot and meta line, and no pixels. The rule is
    /// one function now precisely because it has to be the same at both doors.
    #[test]
    fn docking_a_picture_takes_the_texture_lane_back_and_a_document_gives_it_up() {
        let seat = PreviewSurface::Seat(SeatId(11));
        let other = PreviewSurface::Seat(SeatId(12));
        let window = PreviewSurface::Float(4_u64);

        assert_eq!(
            preview_lane_after_landing(None, seat, true),
            Some(seat),
            "a picture docked into a pane is the picture on the lane"
        );
        assert_eq!(
            preview_lane_after_landing(Some(other), seat, true),
            Some(seat),
            "and it is the pane it landed on, not the one that had the lane"
        );
        assert_eq!(
            preview_lane_after_landing(Some(seat), seat, false),
            None,
            "a document landing where the lane's picture was gives the lane up"
        );
        assert_eq!(
            preview_lane_after_landing(Some(other), seat, false),
            Some(other),
            "and takes nothing from a pane that was not this one"
        );
        assert_eq!(
            preview_lane_after_landing(Some(other), window, true),
            Some(other),
            "a window paints its own picture and never takes the lane"
        );
        assert_eq!(
            preview_lane_after_landing(None, window, true),
            None,
            "not even when the lane is free"
        );
    }

    /// The other half of the ledger's contract: an outstanding question belongs
    /// to a *surface*, so it goes away with it. A pending target that outlived
    /// its pane would be an answer routed to a host that no longer exists — and,
    /// worse, a target a later picture could match by accident.
    #[test]
    fn an_in_flight_resample_cannot_outlive_the_surface_that_asked_for_it() {
        let seat = PreviewSurface::Seat(SeatId(9));
        let target: PeekThumbnailTarget = ("push-pin".to_owned(), 64, 64);
        let mut panes = PreviewPanes::default();
        panes.entry(seat).image = Some(pending_picture("push-pin.png", target.clone()));
        assert_eq!(panes.awaiting_scale(&target), Some(seat));

        panes.remove(seat);
        assert_eq!(
            panes.awaiting_scale(&target),
            None,
            "the pane closed and took its question with it"
        );

        // And the same when the surface stays but stops showing a picture.
        panes.entry(seat).image = Some(pending_picture("push-pin.png", target.clone()));
        panes.entry(seat).image = None;
        assert_eq!(
            panes.awaiting_scale(&target),
            None,
            "a surface that gave up its picture is not waiting on one"
        );
    }

    #[test]
    fn preview_resize_storm_reuses_the_shared_quiet_boundary() {
        let start = Instant::now();
        let last = start + Duration::from_millis(90);
        let mut preview = PreviewImageState::new(PathBuf::from("storm.png"));
        preview.defer_scale_settle(start);
        preview.defer_scale_settle(start + Duration::from_millis(40));
        preview.defer_scale_settle(last);

        assert!(
            !preview.finish_scale_settle_if_quiet(
                last + WINDOW_RESIZE_QUIET - Duration::from_millis(1)
            )
        );
        assert!(preview.finish_scale_settle_if_quiet(last + WINDOW_RESIZE_QUIET));
        assert_eq!(preview.scale_settle_deadline, None);
        assert!(!preview.finish_scale_settle_if_quiet(last + WINDOW_RESIZE_QUIET));
    }

    /// **A zoom is a settle and a pan is not**, which is what keeps a drag off
    /// the resample lane and a wheel on it.
    ///
    /// Measured before this was wired up (4000×3000 PNG, ten detents): seven
    /// exact-size questions went to the lane, it had time to answer three, and
    /// two of the three were sizes the gesture had already travelled past — so
    /// the raster on screen jumped twice on its way to the one that was asked
    /// for. Deferring the question to the boundary the resize gesture already
    /// keeps leaves exactly one pass, at the size the hand stopped on.
    #[test]
    fn a_scale_starts_the_settle_again_and_a_pan_never_does() {
        let fit = ImageZoom::FIT;
        let bigger = ImageZoom::scaled(1.25);
        assert!(
            image_zoom_settles(fit, bigger),
            "a wheel that changed the scale owes a new exact-size raster"
        );
        assert!(
            image_zoom_settles(bigger, fit),
            "and so does one that gave it back"
        );

        let carried = ImageZoom {
            pan: [40.0, -18.0],
            ..bigger
        };
        assert!(
            !image_zoom_settles(bigger, carried),
            "a drag moves the picture across a raster it already holds, so the \
             lane is asked nothing"
        );
        assert!(
            !image_zoom_settles(
                carried,
                ImageZoom {
                    pan: [-7.0, 3.0],
                    ..bigger
                }
            ),
            "and the next move of the same drag asks it nothing either"
        );
    }

    // ── ticket #60: the picture zooms and pans ──────────────────────────────

    /// A 1000×500 body is a convenient one to read the fractions off: the image
    /// column is 860 × 350, so a 2000×1000 picture fits to 350 tall and a
    /// 100×50 one is drawn at its own size rather than blown up to fill it.
    const ZOOM_BODY: [f32; 4] = [100.0, 200.0, 1100.0, 700.0];

    fn rect_size(rect: [f32; 4]) -> (f32, f32) {
        (rect[2] - rect[0], rect[3] - rect[1])
    }

    fn assert_close(left: f32, right: f32, what: &str) {
        assert!((left - right).abs() < 0.01, "{what}: {left} is not {right}");
    }

    #[test]
    fn fit_contains_the_picture_in_the_image_column_and_never_enlarges_it() {
        let fitted = image_destination(ZOOM_BODY, [2000, 1000], ImageZoom::FIT);
        let (width, height) = rect_size(fitted);
        assert_close(height, 350.0, "height fills the column's 70%");
        assert_close(width, 700.0, "and the aspect ratio decides the width");
        assert_close(
            (fitted[0] + fitted[2]) / 2.0,
            600.0,
            "centred on the whole body, not on the column",
        );
        assert_close((fitted[1] + fitted[3]) / 2.0, 450.0, "vertically too");

        let small = image_destination(ZOOM_BODY, [100, 50], ImageZoom::FIT);
        assert_eq!(
            rect_size(small),
            (100.0, 50.0),
            "a small picture is drawn at its own size; Fit contains, it does not stretch"
        );
    }

    #[test]
    fn a_hundred_percent_draws_one_image_pixel_per_screen_pixel_and_centres_it() {
        let drawn = image_destination(ZOOM_BODY, [400, 300], ImageZoom::scaled(1.0));
        assert_eq!(rect_size(drawn), (400.0, 300.0));
        assert_close((drawn[0] + drawn[2]) / 2.0, 600.0, "centred");
        assert_close((drawn[1] + drawn[3]) / 2.0, 450.0, "centred");
        assert_eq!(
            image_destination(ZOOM_BODY, [400, 300], ImageZoom::FIT),
            drawn,
            "and this picture's Fit happens to be 100% too, because Fit never enlarges"
        );
    }

    #[test]
    fn a_zoomed_picture_may_be_carried_only_until_its_own_edge_reaches_the_bodys() {
        let image = [400_u32, 300];
        // 250% of 400×300 is 1000×750: one axis exactly the body's width, the
        // other 250px taller than its 500.
        let centred = image_destination(ZOOM_BODY, image, ImageZoom::scaled(2.5));
        assert_eq!(rect_size(centred), (1000.0, 750.0));

        let carried = image_destination(
            ZOOM_BODY,
            image,
            ImageZoom {
                mode: ImageZoomMode::Scale(2.5),
                pan: [40.0, 60.0],
            },
        );
        assert_close(
            carried[0],
            centred[0],
            "an axis with no overflow does not move at all",
        );
        assert_close(carried[1], centred[1] + 60.0, "the other one does");

        let overrun = image_destination(
            ZOOM_BODY,
            image,
            ImageZoom {
                mode: ImageZoomMode::Scale(2.5),
                pan: [0.0, 9000.0],
            },
        );
        assert_close(
            overrun[1],
            ZOOM_BODY[1],
            "and stops when its own top edge reaches the body's, never opening a gap",
        );
        assert_close(overrun[3], ZOOM_BODY[1] + 750.0, "the far edge follows it");

        let under = image_destination(
            ZOOM_BODY,
            image,
            ImageZoom {
                mode: ImageZoomMode::Scale(0.5),
                pan: [500.0, 500.0],
            },
        );
        assert_eq!(
            under,
            image_destination(ZOOM_BODY, image, ImageZoom::scaled(0.5)),
            "a picture smaller than the body is centred whatever the pan says"
        );
    }

    #[test]
    fn the_scale_is_clamped_to_a_tenth_and_eight_times_the_native_pixels() {
        let image = [400_u32, 300];
        assert_eq!(
            rect_size(image_destination(
                ZOOM_BODY,
                image,
                ImageZoom::scaled(1000.0)
            )),
            (400.0 * IMAGE_ZOOM_MAX, 300.0 * IMAGE_ZOOM_MAX)
        );
        assert_eq!(
            rect_size(image_destination(ZOOM_BODY, image, ImageZoom::scaled(0.0))),
            (400.0 * IMAGE_ZOOM_MIN, 300.0 * IMAGE_ZOOM_MIN)
        );
    }

    /// The whole point of zooming about the pointer: whatever pixel of the
    /// picture the hand was on stays under the hand.
    #[test]
    fn zooming_about_a_point_leaves_that_point_where_it_was() {
        // Read off `image_destination`'s own arithmetic: a picture point `u`
        // from the picture's centre lands at `centre + pan + u * scale`.
        let anchor_at =
            |scale: f32, pan: [f32; 2], u: [f32; 2]| [pan[0] + u[0] * scale, pan[1] + u[1] * scale];
        let (old, new) = (0.4_f32, 1.7_f32);
        let pan = [37.0, -12.0];
        // The pointer, measured from the body's centre.
        let point = [180.0, -95.0];
        let u = [(point[0] - pan[0]) / old, (point[1] - pan[1]) / old];
        assert_eq!(anchor_at(old, pan, u), point);

        let moved = zoom_about(point, old, new, pan);
        let after = anchor_at(new, moved, u);
        assert_close(after[0], point[0], "the anchor did not move sideways");
        assert_close(after[1], point[1], "nor down");

        assert_eq!(
            zoom_about(point, old, old, pan),
            pan,
            "and a zoom that changes nothing moves nothing"
        );
    }

    #[test]
    fn a_wheel_notch_over_the_picture_zooms_about_the_pointer() {
        let image = [400_u32, 300];
        // Fit for this picture is 100%, so the first notch out of Fit is 125%.
        let pointer = [900.0, 300.0];
        let one = image_zoom_notch(ImageZoom::FIT, 1.0, ZOOM_BODY, image, pointer);
        assert_eq!(one.mode, ImageZoomMode::Scale(IMAGE_ZOOM_STEP));

        // The anchor is asked of a picture that is *already* larger than the
        // body on both axes, because that is the only state in which an anchor
        // can be honoured at all: on an axis with no overflow the clamp centres
        // the picture, and centring is a stronger promise than the pointer's.
        let held = ImageZoom::scaled(3.0);
        let before = image_destination(ZOOM_BODY, image, held);
        let zoomed = image_zoom_notch(held, 1.0, ZOOM_BODY, image, pointer);
        let after = image_destination(ZOOM_BODY, image, zoomed);
        for axis in 0..2 {
            // Where the pointer sat inside the picture, as a fraction of it.
            let was = (pointer[axis] - before[axis]) / (before[axis + 2] - before[axis]);
            let now = (pointer[axis] - after[axis]) / (after[axis + 2] - after[axis]);
            assert_close(now, was, "the same point of the picture is under the hand");
        }

        let down = image_zoom_notch(one, -1.0, ZOOM_BODY, image, pointer);
        assert_eq!(
            down.mode,
            ImageZoomMode::Scale(1.0),
            "and the notch is multiplicative, so one back is exactly where it started"
        );

        assert_eq!(
            image_zoom_notch(
                ImageZoom::scaled(IMAGE_ZOOM_MAX),
                1.0,
                ZOOM_BODY,
                image,
                pointer
            ),
            ImageZoom::scaled(IMAGE_ZOOM_MAX),
            "a notch at the end of the road is spent on nothing and moves nothing"
        );
    }

    /// **A detent delivered in pieces is worth exactly one detent** — the claim
    /// `docs/HANDOFF-2026-08-21.md` §5 ⑮/⑳ made against this gesture, checked
    /// rather than inherited.
    ///
    /// That report reasoned by analogy from the focus card's aim, which shares
    /// [`wheel_zoom_notches`] and *did* lose the remainder: the aim spends whole
    /// rows, so it takes `trunc` and had to grow [`CardAim`] to carry the
    /// fraction over. The picture's zoom has no such floor. It is continuous in
    /// the notch count — `IMAGE_ZOOM_STEP.powf(notches)` — and `s^a · s^b =
    /// s^(a+b)`, so the six twenty-unit reports a precision touchpad sends per
    /// detent compose into the same 125% the one report of a mouse gets, with
    /// nothing carried and nothing dropped.
    ///
    /// Confirmed on the machine as well as here (`ui-probe wheel -Step 20`, six
    /// reports): 0.9832 → 1.0204 → 1.0591 → 1.0992 → 1.1409 → 1.1841 → 1.2290,
    /// which is 0.9832 × 1.25 to four figures, and every report moved the
    /// picture rather than six of them moving it once.
    #[test]
    fn a_detent_delivered_in_pieces_zooms_exactly_as_one_detent() {
        let image = [400_u32, 300];
        let pointer = [900.0, 300.0];
        let whole = image_zoom_notch(ImageZoom::FIT, 1.0, ZOOM_BODY, image, pointer);

        // What Win32 sends when a high-resolution wheel or a precision touchpad
        // turns one detent: six reports of twenty, not one of a hundred and
        // twenty.
        let piece = MouseScrollDelta::PixelDelta(PhysicalPosition::new(0.0, 20.0));
        let mut stepped = ImageZoom::FIT;
        for report in 0..6 {
            let moved = image_zoom_notch(
                stepped,
                wheel_zoom_notches(piece),
                ZOOM_BODY,
                image,
                pointer,
            );
            assert_ne!(
                moved, stepped,
                "report {report} of the detent moved the picture by nothing"
            );
            stepped = moved;
        }

        let (ImageZoomMode::Scale(whole), ImageZoomMode::Scale(stepped)) =
            (whole.mode, stepped.mode)
        else {
            panic!("a notch out of Fit resolves to a scale");
        };
        assert_close(
            stepped,
            whole,
            "six pieces of a detent are the detent, with no remainder thrown away",
        );
    }

    #[test]
    fn a_wheel_event_is_counted_in_detents_however_the_driver_reports_it() {
        assert_eq!(
            wheel_zoom_notches(MouseScrollDelta::LineDelta(0.0, 1.0)),
            1.0
        );
        assert_eq!(
            wheel_zoom_notches(MouseScrollDelta::LineDelta(0.0, -2.0)),
            -2.0
        );
        assert_eq!(
            wheel_zoom_notches(MouseScrollDelta::PixelDelta(PhysicalPosition::new(
                0.0, 120.0
            ))),
            1.0
        );
    }

    /// One seat, named the way a card aim names one.
    fn aim_seat(tab: u64, seat: u64) -> LeafId {
        LeafId {
            tab: TabId(tab),
            seat: SeatId(seat),
        }
    }

    /// A driver that reports travel rather than detents, `y` pixels of it.
    fn wheel_pixels(y: f64) -> MouseScrollDelta {
        MouseScrollDelta::PixelDelta(PhysicalPosition::new(0.0, y))
    }

    /// **A sixth of a detent, six times, is one row** (user report 2026-08-21:
    /// "turning up works, but I have to turn for ages before it moves").
    ///
    /// A high-resolution wheel and a precision touchpad both report one detent
    /// as a run of small travels — 20 pixels at a time against Win32's 120 —
    /// and each of those on its own rounds to no rows at all. Rounding each
    /// event in isolation throws the whole turn away, which is what the report
    /// is describing; the fraction is *carried* instead, and the row falls the
    /// moment the sixth nudge completes the detent.
    #[test]
    fn six_sixths_of_a_detent_add_up_to_one_row() {
        let mut aim = None;
        let seat = aim_seat(1, 1);
        let steps: Vec<i32> = (0..6)
            .map(|_| CardAim::spend(&mut aim, seat, wheel_pixels(20.0)))
            .collect();
        assert_eq!(
            steps,
            vec![0, 0, 0, 0, 0, 1],
            "a detent delivered in six pieces moves exactly one row, on the piece that completes it"
        );
    }

    /// The standard mouse is not made slower by the carry: a detent that arrives
    /// whole is one row on arrival, and a merged burst is worth its own count.
    #[test]
    fn a_whole_detent_is_one_row_the_moment_it_lands() {
        let mut aim = None;
        let seat = aim_seat(1, 1);
        assert_eq!(
            CardAim::spend(&mut aim, seat, MouseScrollDelta::LineDelta(0.0, 1.0)),
            1
        );
        assert_eq!(
            CardAim::spend(&mut aim, seat, MouseScrollDelta::LineDelta(0.0, 1.0)),
            1
        );
        assert_eq!(
            CardAim::spend(&mut aim, seat, MouseScrollDelta::LineDelta(0.0, 3.0)),
            3,
            "a flick merged into one burst is worth every detent in it"
        );
        assert_eq!(
            CardAim::spend(&mut aim, seat, wheel_pixels(120.0)),
            1,
            "and a driver reporting travel says the same thing in its own currency"
        );
    }

    /// **A hand that changes its mind does not get the fraction it was owed.**
    ///
    /// Half a detent upward is a promise about *up*; spending it on the way down
    /// would make the first row down arrive early or late depending on something
    /// the reader did before and cannot see.
    #[test]
    fn turning_the_other_way_forgets_the_fraction_it_was_owed() {
        let mut aim = None;
        let seat = aim_seat(1, 1);
        assert_eq!(CardAim::spend(&mut aim, seat, wheel_pixels(60.0)), 0);
        assert_eq!(
            CardAim::spend(&mut aim, seat, wheel_pixels(-120.0)),
            -1,
            "a whole detent down is one row down, not half of one"
        );
        assert_eq!(CardAim::spend(&mut aim, seat, wheel_pixels(-60.0)), 0);
        assert_eq!(
            CardAim::spend(&mut aim, seat, wheel_pixels(-60.0)),
            -1,
            "and the downward halves add up among themselves"
        );
    }

    /// **The bare wheel is the column's, whatever else is held down** (user
    /// ruling 2026-08-21).
    ///
    /// The list this window puts under the pointer is the thing with content out
    /// of sight, so the gesture every other list in the product answers is the
    /// one this one answers too. `Shift` is named here on purpose: it is spent
    /// twice already on the wheel — the preview body's other axis, and
    /// [`wheel_route`]'s "this notch is mine, not the program's" — so a reader
    /// holding it over the column gets the list, not a third meaning.
    #[test]
    fn a_bare_notch_over_the_column_is_the_lists() {
        for held in [
            ModifiersState::empty(),
            ModifiersState::SHIFT,
            ModifiersState::CONTROL,
            ModifiersState::CONTROL.union(ModifiersState::SHIFT),
            ModifiersState::SUPER,
        ] {
            assert_eq!(
                column_notch(held),
                ColumnNotch::List,
                "{held:?} over the card column has to scroll the card column"
            );
        }
    }

    /// **`Alt` is the aim, and nothing else is.**
    ///
    /// The second half names `Ctrl+Alt` deliberately: the shortcut table's AltGr
    /// discipline is about chords that would swallow a character, and a notch is
    /// not a character — so a reader whose hand is on AltGr still aims rather
    /// than discovering that the gesture has holes in it.
    #[test]
    fn alt_and_a_notch_aims_the_seat_under_the_pointer() {
        for held in [
            ModifiersState::ALT,
            ModifiersState::ALT.union(ModifiersState::SHIFT),
            ModifiersState::ALT.union(ModifiersState::CONTROL),
        ] {
            assert_eq!(
                column_notch(held),
                ColumnNotch::Aim,
                "{held:?} is a wheel with Alt held, which aims"
            );
        }
    }

    /// **The fraction belongs to the seat it was turned at**, not to the window.
    ///
    /// Moving the pointer to another seat — or to another card — starts that
    /// seat's aim from nothing, because a carry that followed the pointer would
    /// move a window the reader never turned the wheel over.
    #[test]
    fn the_fraction_belongs_to_the_seat_it_was_turned_at() {
        let mut aim = None;
        let half = wheel_pixels(60.0);
        assert_eq!(CardAim::spend(&mut aim, aim_seat(1, 1), half), 0);
        assert_eq!(
            CardAim::spend(&mut aim, aim_seat(1, 2), half),
            0,
            "the seat next door did not inherit the half detent"
        );
        assert_eq!(CardAim::spend(&mut aim, aim_seat(1, 2), half), 1);
        assert_eq!(
            CardAim::spend(&mut aim, aim_seat(2, 1), half),
            0,
            "and neither did the same-numbered seat on another card"
        );
        assert_eq!(CardAim::spend(&mut aim, aim_seat(2, 1), half), 1);
    }

    #[test]
    fn a_double_click_swings_between_fit_and_a_hundred_percent_and_lands_centred() {
        let hundred = image_zoom_toggled(ImageZoom::FIT);
        assert_eq!(hundred.mode, ImageZoomMode::Scale(1.0));
        assert_eq!(
            hundred.pan,
            [0.0, 0.0],
            "a toggle is a command and lands on the middle, not on wherever the second click fell"
        );
        assert_eq!(image_zoom_toggled(hundred), ImageZoom::FIT);
        assert_eq!(
            image_zoom_toggled(ImageZoom {
                mode: ImageZoomMode::Scale(3.0),
                pan: [90.0, 4.0],
            }),
            ImageZoom::FIT,
            "and from anywhere else it goes home"
        );
    }

    #[test]
    fn two_presses_in_one_place_are_a_double_click_and_a_third_starts_over() {
        let surface = PreviewSurface::Seat(SeatId(2));
        let now = Instant::now();
        let mut clicks = ImageClicks::default();
        assert!(!clicks.register(surface, [400.0, 300.0], now));
        assert!(clicks.register(surface, [403.0, 302.0], now + Duration::from_millis(90)));
        assert!(
            !clicks.register(surface, [403.0, 302.0], now + Duration::from_millis(120)),
            "the pair was spent; a third press begins a new one"
        );

        let mut slow = ImageClicks::default();
        assert!(!slow.register(surface, [400.0, 300.0], now));
        assert!(!slow.register(
            surface,
            [400.0, 300.0],
            now + MULTI_CLICK_INTERVAL + Duration::from_millis(1)
        ));

        let mut wandered = ImageClicks::default();
        assert!(!wandered.register(surface, [400.0, 300.0], now));
        assert!(!wandered.register(surface, [480.0, 300.0], now + Duration::from_millis(90)));

        let mut elsewhere = ImageClicks::default();
        assert!(!elsewhere.register(surface, [400.0, 300.0], now));
        assert!(!elsewhere.register(
            PreviewSurface::Seat(SeatId(3)),
            [400.0, 300.0],
            now + Duration::from_millis(90)
        ));
    }

    #[test]
    fn the_four_zoom_keys_step_about_the_body_centre_and_name_the_two_ends() {
        let image = [400_u32, 300];
        let key = |text: &str| Key::Character(text.into());
        assert_eq!(
            image_zoom_key(ImageZoom::FIT, &key("+"), ZOOM_BODY, image),
            Some(ImageZoom::scaled(IMAGE_ZOOM_STEP)),
            "a key has no pointer, so its anchor is the centre and the pan stays nothing"
        );
        assert_eq!(
            image_zoom_key(ImageZoom::FIT, &key("="), ZOOM_BODY, image),
            image_zoom_key(ImageZoom::FIT, &key("+"), ZOOM_BODY, image),
            "`=` is the unshifted `+` and means the same thing"
        );
        assert_eq!(
            image_zoom_key(ImageZoom::scaled(1.0), &key("-"), ZOOM_BODY, image),
            Some(ImageZoom::scaled(1.0 / IMAGE_ZOOM_STEP))
        );
        assert_eq!(
            image_zoom_key(ImageZoom::scaled(3.0), &key("0"), ZOOM_BODY, image),
            Some(ImageZoom::FIT)
        );
        assert_eq!(
            image_zoom_key(ImageZoom::FIT, &key("1"), ZOOM_BODY, image),
            Some(ImageZoom::scaled(1.0))
        );
        assert_eq!(
            image_zoom_key(ImageZoom::FIT, &key("j"), ZOOM_BODY, image),
            None,
            "and every other key falls through to whatever the surface does with it"
        );
        assert_eq!(
            image_zoom_key(
                ImageZoom::FIT,
                &Key::Named(NamedKey::ArrowDown),
                ZOOM_BODY,
                image
            ),
            None
        );
    }

